INSERT INTO storage.buckets (id,name,public,file_size_limit,allowed_mime_types) VALUES ('crm-documentos','crm-documentos',false,20971520,ARRAY['application/pdf','image/jpeg','image/png','image/webp']) ON CONFLICT (id) DO NOTHING;
CREATE POLICY crm_documents_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'crm-documentos' AND EXISTS (SELECT 1 FROM public.leads l WHERE l.id::text = (storage.foldername(name))[1] AND (private.current_crm_role() IN ('admin','gestor') OR l.corretor = private.current_crm_broker())));
CREATE POLICY crm_documents_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'crm-documentos' AND EXISTS (SELECT 1 FROM public.leads l WHERE l.id::text = (storage.foldername(name))[1] AND (private.current_crm_role() IN ('admin','gestor') OR l.corretor = private.current_crm_broker())) AND lower(storage.extension(name)) IN ('pdf','jpg','jpeg','png','webp'));
CREATE POLICY crm_documents_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'crm-documentos' AND EXISTS (SELECT 1 FROM public.leads l WHERE l.id::text = (storage.foldername(name))[1] AND (private.current_crm_role() IN ('admin','gestor') OR l.corretor = private.current_crm_broker())));